entries[192843] = { ["name"] = "Glyphe 'Knisternder Kranichblitz'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)\nStellt eine Glyphe 'Knisternder Kranichblitz' her.\nVerkäufer:\nJang Federpfote\nZone:\nDalaran\nKosten:\n35\n\nKlassen: Mönch\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer visuelle Effekt Eures Zaubers 'Knisternder Jadeblitz' hat nun die Farbe des Roten Kranichs. Exklusiv mit: Glyphe 'Knisternder Tigerblitz'\n11" }
