entries[192853] = { ["name"] = "Königsmord", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt das in den Königsmördern enthaltene todbringende Gift auf Euren Gegner und fügt ihm so sofort (81% + 81%) Naturschaden und zusätzlich (52.92% der Angriffskraft) Naturschaden im Verlauf von 14 Sek. zu.\n\nJedes Mal, wenn Ihr ein von 'Königsmord' betroffenes Ziel mit tödlichem Gift vergiftet, wird der Schaden von 'Königsmord' um 15% erhöht.\n\nGewährt 1 Combopunkt." }
